<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/admin_shell.php';security_headers();require_admin();
$db=database();$state=admin_activity_resolution($db);$activity=$state['activity'];if(!$activity){header('Location: /admin/activities.php');exit;}$activityId=(int)$activity['id'];
function registration_payload(array $row): array {return json_decode((string)($row['payload_json']??''),true)?:[];}
function registration_snapshot(array $row): array {return json_decode((string)($row['form_snapshot_json']??''),true)?:[];}
function registration_fields(array $row): array {$map=[];foreach(registration_snapshot($row)['fields']??[] as $field)if(is_array($field)&&isset($field['id']))$map[(string)$field['id']]=$field;return $map;}
function registration_value_label(array $field,mixed $value): string {if(is_array($value))return implode(', ',array_map(fn($item)=>registration_value_label($field,(string)$item),$value));$raw=(string)$value;foreach($field['options']??[] as $option)if(is_array($option)&&(string)($option['value']??'')===$raw)return (string)($option['label']??$raw);return $raw;}
function registration_name(array $row): string {$p=registration_payload($row);return trim((string)($p['name']??$p['full_name']??''))?:trim((string)($p['email']??''))?:'Inscrição #'.(int)$row['id'];}
function registration_status_label(array $row): string {if(($row['status']??'')==='archived')return 'Cancelada';if((int)($row['cohort_id']??0)>0&&student_account_submission_confirmed($row))return 'Com turma';if(student_account_submission_confirmed($row))return 'Confirmada · sem turma';return 'Aguardando pagamento';}
function registration_status_tone(array $row): string {if(($row['status']??'')==='archived')return 'danger';if((int)($row['cohort_id']??0)>0&&student_account_submission_confirmed($row))return 'good';return 'attention';}
function registration_admin_url(int $activityId,int $courseId,int $cohortId=0,int $submissionId=0,string $filter='',string $search='',int $page=1): string {$args=['activity'=>$activityId,'course'=>$courseId];if($cohortId>0)$args['cohort']=$cohortId;if($submissionId>0)$args['submission']=$submissionId;if($filter!=='')$args['status']=$filter;if($search!=='')$args['q']=$search;if($page>1)$args['page']=$page;return '/admin/registrations.php?'.http_build_query($args);}
function registration_availability_summary(array $rows): array {$counts=[];foreach($rows as $row){$payload=registration_payload($row);$fields=registration_fields($row);foreach(['availability','preferred_days','preferred_time'] as $key){$value=$payload[$key]??null;if($value===null||$value===''||$value===[])continue;foreach(is_array($value)?$value:[$value] as $item){$label=trim(registration_value_label($fields[$key]??[],(string)$item));if($label!=='')$counts[$label]=($counts[$label]??0)+1;}}}arsort($counts,SORT_NUMERIC);return $counts;}
$courses=course_list($db,$activityId);$courseId=max(0,(int)($_GET['course']??$_POST['filter_course_id']??0));$course=$courseId>0?course_by_id($db,$courseId):null;if(!$course||(int)$course['activity_id']!==$activityId){if(count($courses)===1){header('Location: '.admin_course_url($activityId,(int)$courses[0]['id'],'registrations'),true,302);exit;}header('Location: /admin/courses.php?activity='.$activityId,true,302);exit;}
$cohortId=max(0,(int)($_GET['cohort']??0));$cohortOptions=course_cohorts_for_course($db,$courseId);if($cohortId>0&&!array_filter($cohortOptions,static fn(array $row): bool=>(int)$row['id']===$cohortId)){$_SESSION['admin_registrations_notice']='A turma solicitada não pertence a este curso.';header('Location: '.admin_course_url($activityId,$courseId,'cohorts'),true,302);exit;}
$filter=(string)($_GET['status']??'');$allowedFilters=['','pending','unassigned','assigned','cancelled'];if(!in_array($filter,$allowedFilters,true))$filter='';$search=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$pageSize=50;$selectedId=max(0,(int)($_GET['submission']??0));
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!verify_csrf('course-registrations',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}$id=(int)($_POST['submission_id']??0);$action=(string)($_POST['action']??'');
 try{$stmt=$db->prepare("SELECT s.* FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id WHERE s.id=? AND s.course_id=? AND f.activity_id=? AND f.purpose='enrollment'");$stmt->execute([$id,$courseId,$activityId]);$row=$stmt->fetch()?:throw new RuntimeException('Inscrição não encontrada neste curso.');$now=utc_now();$paymentNote=array_key_exists('payment_note',$_POST)?trim((string)$_POST['payment_note']):(string)($row['payment_note']??'');
  if($action==='confirm')$db->prepare("UPDATE cms_form_submissions SET status='converted',payment_status='paid',payment_confirmed_at=?,payment_note=?,updated_at=? WHERE id=?")->execute([$now,$paymentNote,$now,$id]);
  elseif($action==='pending')$db->prepare("UPDATE cms_form_submissions SET status='new',payment_status='pending',payment_confirmed_at=NULL,payment_note=?,updated_at=? WHERE id=?")->execute([$paymentNote,$now,$id]);
  elseif($action==='archive')$db->prepare("UPDATE cms_form_submissions SET status='archived',payment_note=?,updated_at=? WHERE id=?")->execute([$paymentNote,$now,$id]);
  elseif($action==='assign_cohort')course_registration_assign_cohort($db,$id,$courseId,(int)($_POST['cohort_id']??0));
  elseif($action==='unassign_cohort')course_registration_unassign_cohort($db,$id,$courseId);
  elseif($action==='delete_registration')admin_registration_delete($db,$id,$activityId);else throw new RuntimeException('Ação inválida.');
  student_enrollment_reconcile_confirmed($db,$activityId);$_SESSION['admin_registrations_notice']='Alteração salva.';
 }catch(Throwable $e){$_SESSION['admin_registrations_notice']='Não foi possível concluir: '.$e->getMessage();}
 $redirectCohort=max(0,(int)($_POST['filter_cohort_id']??0));$redirectFilter=(string)($_POST['filter_status']??'');$redirectSearch=trim((string)($_POST['search_q']??''));$redirectPage=max(1,(int)($_POST['list_page']??1));header('Location: '.registration_admin_url($activityId,$courseId,$redirectCohort,$action==='delete_registration'?0:$id,$redirectFilter,$redirectSearch,$redirectPage),true,303);exit;
}
$baseWhere=["f.activity_id=?","f.purpose='enrollment'",'s.course_id=?'];$baseArgs=[$activityId,$courseId];if($cohortId>0){$baseWhere[]='s.cohort_id=?';$baseArgs[]=$cohortId;}$statsWhere=implode(' AND ',$baseWhere);$statsStmt=$db->prepare("SELECT SUM(CASE WHEN s.status!='archived' THEN 1 ELSE 0 END) total,SUM(CASE WHEN s.status!='archived' AND COALESCE(s.payment_status,'pending')!='paid' AND s.status!='converted' THEN 1 ELSE 0 END) pending,SUM(CASE WHEN s.status!='archived' AND (s.payment_status='paid' OR s.status='converted') AND s.cohort_id IS NULL THEN 1 ELSE 0 END) unassigned,SUM(CASE WHEN s.status!='archived' AND s.cohort_id IS NOT NULL THEN 1 ELSE 0 END) assigned FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id WHERE $statsWhere");$statsStmt->execute($baseArgs);$stats=$statsStmt->fetch()?:[];
$where=$baseWhere;$args=$baseArgs;if($filter==='pending')$where[]="s.status!='archived' AND COALESCE(s.payment_status,'pending')!='paid' AND s.status!='converted'";elseif($filter==='unassigned')$where[]="s.status!='archived' AND (s.payment_status='paid' OR s.status='converted') AND s.cohort_id IS NULL";elseif($filter==='assigned')$where[]="s.status!='archived' AND s.cohort_id IS NOT NULL";elseif($filter==='cancelled')$where[]="s.status='archived'";else $where[]="s.status!='archived'";if($search!==''){$where[]='(s.payload_json LIKE ? OR CAST(s.id AS TEXT) LIKE ?)';$like='%'.$search.'%';array_push($args,$like,$like);}$whereSql=implode(' AND ',$where);
$count=$db->prepare("SELECT COUNT(*) FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id WHERE $whereSql");$count->execute($args);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$pageSize));if($page>$pages)$page=$pages;$offset=($page-1)*$pageSize;
$stmt=$db->prepare("SELECT s.*,f.title form_title,cc.title cohort_title FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id LEFT JOIN course_cohorts cc ON cc.id=s.cohort_id WHERE $whereSql ORDER BY s.created_at DESC,s.id DESC LIMIT $pageSize OFFSET $offset");$stmt->execute($args);$rows=$stmt->fetchAll();
$selected=null;if($selectedId>0){$stmt=$db->prepare("SELECT s.*,f.title form_title,cc.title cohort_title FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id LEFT JOIN course_cohorts cc ON cc.id=s.cohort_id WHERE s.id=? AND s.course_id=? AND f.activity_id=? AND f.purpose='enrollment'");$stmt->execute([$selectedId,$courseId,$activityId]);$selected=$stmt->fetch()?:null;}
$availabilityStmt=$db->prepare("SELECT s.payload_json,s.form_snapshot_json FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id WHERE s.course_id=? AND s.status!='archived' AND f.purpose='enrollment' ORDER BY s.created_at DESC");$availabilityStmt->execute([$courseId]);$availability=registration_availability_summary($availabilityStmt->fetchAll());
$notice=(string)($_SESSION['admin_registrations_notice']??'');unset($_SESSION['admin_registrations_notice']);$noticeTone=str_starts_with($notice,'Não foi possível')?'error':'success';
admin_shell_start('registrations','Inscrições',$state,['/assets/admin-operations.css','/assets/admin-registration.css','/assets/admin-teaching.css']);?>
<?php if($notice!==''):?><div class="admin-notice <?=h($noticeTone)?>" role="<?=$noticeTone==='error'?'alert':'status'?>"><?=h($notice)?></div><?php endif;?>
<?php admin_course_context($course,$activityId,'registrations','Entrada e atribuição de turma.');?>
<?php if(!$selected):?>
<nav class="admin-status-tabs" aria-label="Estado das inscrições"><a href="<?=h(registration_admin_url($activityId,$courseId))?>"<?=$filter===''?' aria-current="page"':''?>>Ativas <span><?=(int)($stats['total']??0)?></span></a><a href="<?=h(registration_admin_url($activityId,$courseId,0,0,'pending'))?>"<?=$filter==='pending'?' aria-current="page"':''?>>Aguardando pagamento <span><?=(int)($stats['pending']??0)?></span></a><a href="<?=h(registration_admin_url($activityId,$courseId,0,0,'unassigned'))?>"<?=$filter==='unassigned'?' aria-current="page"':''?>>Pagas sem turma <span><?=(int)($stats['unassigned']??0)?></span></a><a href="<?=h(registration_admin_url($activityId,$courseId,0,0,'assigned'))?>"<?=$filter==='assigned'?' aria-current="page"':''?>>Com turma <span><?=(int)($stats['assigned']??0)?></span></a><a href="<?=h(registration_admin_url($activityId,$courseId,0,0,'cancelled'))?>"<?=$filter==='cancelled'?' aria-current="page"':''?>>Canceladas</a></nav>
<form class="admin-data-toolbar" method="get"><input type="hidden" name="activity" value="<?=$activityId?>"><input type="hidden" name="course" value="<?=$courseId?>"><input type="hidden" name="status" value="<?=h($filter)?>"><label>Turma<select name="cohort"><option value="0">Todas as turmas</option><?php foreach($cohortOptions as $item):?><option value="<?=(int)$item['id']?>"<?=$cohortId===(int)$item['id']?' selected':''?>><?=h((string)$item['title'])?></option><?php endforeach;?></select></label><label class="grow">Buscar<input name="q" value="<?=h($search)?>" placeholder="Nome, e-mail, telefone ou número"></label><div class="admin-inline-actions"><button class="admin-button secondary" type="submit">Filtrar</button><?php if($cohortId>0||$search!==''):?><a class="admin-button secondary" href="<?=h(registration_admin_url($activityId,$courseId,0,0,$filter))?>">Limpar</a><?php endif;?></div></form>
<?php if($availability):?><details class="admin-secondary-setup"><summary class="admin-button secondary">Ver disponibilidade agregada</summary><section class="admin-card"><div class="admin-availability-grid"><?php foreach($availability as $label=>$n):?><div class="admin-availability-item"><strong><?=(int)$n?></strong><span><?=h((string)$label)?></span></div><?php endforeach;?></div></section></details><?php endif;?>
<div class="admin-list-summary"><span><?php if($total>0):?>Mostrando <?=($offset+1)?>–<?=min($offset+$pageSize,$total)?> de <?=$total?> inscrição(ões)<?php else:?>Nenhuma inscrição neste filtro<?php endif;?></span></div>
